import{_ as t,o as e,c as p,a5 as c}from"./chunks/framework.BPFk9-tb.js";const i=JSON.parse('{"title":"写作课作业-077","description":"","frontmatter":{"date":"2020-10-19T21:07:19","title":"写作课作业-077","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[],"relativePath":"posts/homework/077.md","filePath":"posts/homework/077.md"}'),a={name:"posts/homework/077.md"};function s(r,o,l,_,k,u){return e(),p("div",null,[...o[0]||(o[0]=[c("<blockquote><p>10.4写作作业：《微信互联网平民创业》之《9. 不能卖货也不能卖课咋办?》</p></blockquote><blockquote><p>让我向你介绍一个任何时候对平⺠都有意义、都非常实用的策略吧，这个策略一共四个字(哈哈!):</p><blockquote><p>退而求其次</p></blockquote></blockquote><p>做软件项目的时候，一开始规划得高大上，基本上能想到的技术，酷炫的功能都写到方案里了，项目拿下来再说。但最终因技术不过关，人力不足，资金不够，往往只能做个半成品，想用吧，用不了，想扔吧，合同在那，想换吧，时间不多了，于是只好硬着头皮，删删减减，继续往下开发，然后好不容易凑个产品出来交付，真正的坑才开始，每天都有处理不完的BUG，用不顺畅的功能。如果一开始没规划那么多，反而更容易看到成果，把产品做得出彩，现在出做产品是先出原型，出MVP就是退而求其次。</p><blockquote><p>我认为这个策略会对所有平⺠⻓期有效:</p><blockquote><p>做本地内容</p></blockquote><p>当然，这样的选择背后，实际上还有更为深刻的决策支撑:</p><blockquote><p>对平⺠来说，微信互联网商业生态，并不是成为领袖的机会，而是成为服务者的机会!</p></blockquote><p>—— 这才是更有价值的选择!</p></blockquote><p>不同的地区有不同的需求和内容，于是对不同地区的人可以做的不同的本地内容，基于多样性的角度，做小众软件，定制化软件也是可以的。</p>",5)])])}const b=t(a,[["render",s]]);export{i as __pageData,b as default};
